'use client'

import { Match } from '@/lib/types'

export default function MatchCard({ match, onPredict }: { 
  match: Match
  onPredict: (match: Match) => void 
}) {
  const getStatusBadge = () => {
    switch (match.status) {
      case 'live':
        return <span className="px-3 py-1 bg-red-500 text-white text-xs font-semibold rounded-full animate-pulse">🔴 LIVE</span>
      case 'upcoming':
        return <span className="px-3 py-1 bg-blue-500 text-white text-xs font-semibold rounded-full">📅 Upcoming</span>
      case 'completed':
        return <span className="px-3 py-1 bg-gray-500 text-white text-xs font-semibold rounded-full">✅ Completed</span>
    }
  }

  return (
    <div className="bg-white rounded-xl shadow-lg p-6 border-2 border-gray-100 hover:border-blue-300 transition">
      <div className="flex justify-between items-start mb-4">
        <h3 className="text-lg font-bold text-gray-800">🏏 PSL Match</h3>
        {getStatusBadge()}
      </div>

      <div className="space-y-3">
        <div className="flex justify-between items-center">
          <span className="font-semibold text-gray-700">{match.team_a}</span>
          {match.status === 'live' && match.batting_team === 'team_a' && (
            <span className="text-xs text-green-600 font-bold">BATTING</span>
          )}
          {match.status === 'live' && (
            <span className="text-lg font-bold text-blue-600">
              {match.current_score_a}/{match.current_wickets_a}
            </span>
          )}
        </div>

        <div className="text-center text-gray-400 font-semibold">VS</div>

        <div className="flex justify-between items-center">
          <span className="font-semibold text-gray-700">{match.team_b}</span>
          {match.status === 'live' && match.batting_team === 'team_b' && (
            <span className="text-xs text-green-600 font-bold">BATTING</span>
          )}
          {match.status === 'live' && (
            <span className="text-lg font-bold text-blue-600">
              {match.current_score_b}/{match.current_wickets_b}
            </span>
          )}
        </div>
      </div>

      {match.status === 'live' && (
        <div className="mt-4 pt-4 border-t text-sm text-gray-600">
          <p>📍 {match.venue}</p>
          <p className="mt-1">Over: {match.current_over}</p>
        </div>
      )}

      {match.status === 'upcoming' && (
        <div className="mt-4 pt-4 border-t text-sm text-gray-600">
          <p>📍 {match.venue}</p>
          <p className="mt-1">🕐 {new Date(match.match_date).toLocaleString()}</p>
        </div>
      )}

      {(match.status === 'live' || match.status === 'upcoming') && (
        <button
          onClick={() => onPredict(match)}
          className="w-full mt-4 bg-gradient-to-r from-blue-600 to-purple-600 text-white py-3 rounded-lg font-semibold hover:shadow-lg transition"
        >
          🎯 Make Predictions
        </button>
      )}
    </div>
  )
}
